from datetime import date, timedelta
import calendar


def recur(start: str, rule: str, count: int) -> list[str]:
    y, m, d = map(int, start.split("-"))
    s = date(y, m, d)
    parts = rule.split()
    kind = parts[0]
    K = int(parts[1])
    res = []
    LIMIT = date(3000, 1, 1)

    def add(dt):
        res.append(dt.isoformat())
        return len(res) >= count

    if kind == "DAILY":
        cur = s
        while cur < LIMIT:
            if add(cur):
                break
            cur += timedelta(days=K)
        return res

    if kind == "WEEKLY":
        codes = ["MO", "TU", "WE", "TH", "FR", "SA", "SU"]
        wds = sorted(codes.index(c) for c in parts[2].split(","))
        monday = s - timedelta(days=s.weekday())
        w = 0
        while monday + timedelta(weeks=w) < LIMIT:
            base = monday + timedelta(weeks=w)
            for wd in wds:
                dt = base + timedelta(days=wd)
                if dt >= s:
                    if add(dt):
                        return res
            w += K
        return res

    if kind == "MONTHLY":
        codes = ["MO", "TU", "WE", "TH", "FR", "SA", "SU"]
        idx = 0
        while True:
            tot = y * 12 + (m - 1) + idx
            yy, mm = divmod(tot, 12)
            mm += 1
            if yy >= 3000:
                break
            dim = calendar.monthrange(yy, mm)[1]
            dt = None
            if len(parts) == 3:
                D = int(parts[2])
                if D == -1:
                    dt = date(yy, mm, dim)
                elif D <= dim:
                    dt = date(yy, mm, D)
            else:
                N = int(parts[2])
                wd = codes.index(parts[3])
                days = [x for x in range(1, dim + 1)
                        if date(yy, mm, x).weekday() == wd]
                if N == -1:
                    dt = date(yy, mm, days[-1])
                elif N <= len(days):
                    dt = date(yy, mm, days[N - 1])
            if dt is not None and dt >= s:
                if add(dt):
                    return res
            idx += K
        return res

    if kind == "YEARLY":
        mm, dd = map(int, parts[2].split("-"))
        yy = y
        while yy < 3000:
            try:
                dt = date(yy, mm, dd)
            except ValueError:
                dt = None
            if dt is not None and dt >= s:
                if add(dt):
                    return res
            yy += K
        return res

    return res
